// Transform PostgreSQL row to Power BI schema
const dbRow = $input.first().json;

// Build Power BI payload matching the 18-field schema
const powerbiPayload = {
  metricId: dbRow.metric_id,
  totalEnquiries: parseInt(dbRow.total_enquiries || 0),
  pipelineValue: parseFloat(dbRow.pipeline_value || 0),
  avgLeadScore: parseFloat(dbRow.avg_lead_score || 0),
  avgResponseTime: parseFloat(dbRow.avg_response_time || 0),
  avgConfidence: parseFloat(dbRow.avg_confidence || 0),
  avgPaxTotal: parseFloat(dbRow.avg_pax_total || 0),
  enquiriesHour: parseInt(dbRow.enquiries_hour || 0),
  pipelineHour: parseFloat(dbRow.pipeline_hour || 0),
  countImmediate: parseInt(dbRow.count_immediate || 0),
  countImportant: parseInt(dbRow.count_important || 0),
  countNotImportant: parseInt(dbRow.count_not_important || 0),
  countWebsite: parseInt(dbRow.count_website || 0),
  countChatbot: parseInt(dbRow.count_chatbot || 0),
  countConsidering: parseInt(dbRow.count_considering || 0),
  countEnquiring: parseInt(dbRow.count_enquiring || 0),
  countShortlisting: parseInt(dbRow.count_shortlisting || 0),
  lastUpdated: new Date(dbRow.last_updated).toISOString()
};

console.log('Power BI KPI payload:', JSON.stringify(powerbiPayload, null, 2));
return [{ json: powerbiPayload }];
